import { writeFile, readFile } from 'node:fs/promises';
import { installFreshSessionNavigation } from '../client-core.js';
const output = new URL('../client.js', import.meta.url);
// Observe a previously generated file before replacing it.
await readFile(output, 'utf8').catch(error => { if (error.code !== 'ENOENT') throw error; });
const body = `// Generated by scripts/build-client.mjs; edit client-core.js instead.\nwindow.__ModuleLoader__.load({\n  id: '@local/dsh-default-auto-review',\n  factory: () => {\n    const install = ${installFreshSessionNavigation.toString()};\n    return {\n      name: 'default-auto-review-navigation',\n      inject: ['uiWorkspace', 'sessions'],\n      apply(ctx) {\n        const dispose = install(ctx);\n        const root = globalThis.document?.documentElement;\n        if (root) root.dataset.dshDefaultAutoReview = '0.1.1';\n        ctx.effect(() => () => {\n          dispose();\n          if (root?.dataset.dshDefaultAutoReview === '0.1.1') delete root.dataset.dshDefaultAutoReview;\n        });\n      },\n    };\n  },\n});\n`;
await writeFile(output, body, 'utf8');
console.log('Built default-auto-review client bundle (0.1.1).');
